#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int w, m;
    cin >> w >> m;
    string answer;
    if (w <= 3) {
        answer = "YES";
    } else {
        long long limit = 10000000000LL; // 1e10
        long long current = 1;
        vector<long long> powersList;
        while (current <= limit) {
            powersList.push_back(current);
            current *= w;
        }
        int size = (int)powersList.size();
        bool found = false;
        int totalSubsets = 1 << size;
        for (int subsetMask = 0; subsetMask < totalSubsets; ++subsetMask) {
            long long total = m;
            for (int idx = 0; idx < size; ++idx) {
                if ((subsetMask & (1 << idx)) != 0) {
                    total += powersList[idx];
                }
            }
            for (int idx = size - 1; idx >= 0; --idx) {
                if ((subsetMask & (1 << idx)) == 0) {
                    if (total - powersList[idx] >= 0) {
                        total -= powersList[idx];
                    }
                }
            }
            if (total == 0) {
                answer = "YES";
                found = true;
                break;
            }
        }
        if (!found) {
            answer = "NO";
        }
    }
    cout << answer;
    return 0;
}
